export type BetaThinkingDroppedInputTransformation = {
  readonly "path": string
  readonly "reason":
    | "model_binding_mismatch"
    | "prefix_binding_mismatch"
    | "organization_binding_mismatch"
    | "end_user_binding_mismatch"
  readonly "type": "thinking_dropped"
}
export const BetaThinkingDroppedInputTransformation = Schema.Struct({
  "path": Schema.String.annotate({
    "title": "Path",
    "description":
      "Where the removed block was in your request, as `messages.{i}.content.{j}`:\n`i` indexes the `messages` array you sent and `j` that message's `content`\narray — the same form error messages use."
  }),
  "reason": Schema.Literals([
    "model_binding_mismatch",
    "prefix_binding_mismatch",
    "organization_binding_mismatch",
    "end_user_binding_mismatch"
  ]).annotate({
    "title": "Reason",
    "description":
      "Which binding check removed the block: `model_binding_mismatch` — it was\ncreated by a model whose reasoning the requested model may not read;\n`prefix_binding_mismatch` — the conversation before it differs from the\nconversation it was created in (the rest of that turn's consecutive thinking\nblocks are removed with it, each with this reason);\n`organization_binding_mismatch` — it was created under a different\norganization (an Anthropic organization, AWS account or Google Cloud project)\nand this organization is not one of its additional organizations;\n`end_user_binding_mismatch` — it was created for a different end user, or\nwas removed by the consumer-organization binding. A block that would fail\nseveral checks reports one reason, in this order of precedence:\n`organization_binding_mismatch`, `end_user_binding_mismatch`,\n`model_binding_mismatch`, `prefix_binding_mismatch`."
  }),
  "type": Schema.Literal("thinking_dropped").annotate({
    "title": "Type",
    "description": "Always `thinking_dropped` for this entry type.",
    "default": "thinking_dropped"
  })
}).annotate({ "title": "ThinkingDroppedInputTransformation", "identifier": "BetaThinkingDroppedInputTransformation" })
export type BetaThinkingMismatchAllowedInputTransformation = {
  readonly "path": string
  readonly "reason":
    | "model_binding_mismatch"
    | "prefix_binding_mismatch"
    | "organization_binding_mismatch"
    | "end_user_binding_mismatch"
  readonly "type": "thinking_mismatch_allowed"
}
export const BetaThinkingMismatchAllowedInputTransformation = Schema.Struct({
  "path": Schema.String.annotate({
    "title": "Path",
    "description":
      "Where the block is in your request, as `messages.{i}.content.{j}`:\n`i` indexes the `messages` array you sent and `j` that message's `content`\narray — the same form error messages use."
  }),
  "reason": Schema.Literals([
    "model_binding_mismatch",
    "prefix_binding_mismatch",
    "organization_binding_mismatch",
    "end_user_binding_mismatch"
  ]).annotate({
    "title": "Reason",
    "description":
      "Which binding check the block failed; the block was shown to the model all\nthe same. Always `prefix_binding_mismatch` today — the conversation before\nthe block differs from the conversation it was created in, or the block\ncarries no record of one on a model that requires it. Were the check\nenforced for this request, the block would have been removed or the request\nrejected (`thinking.block_binding.prefix_mismatch_behavior`). A removal also\ntakes the rest of that turn's consecutive thinking blocks, whereas here each\nblock is checked on its own, so `thinking_mismatch_allowed` entries are a\nlower bound on what enforcement would remove."
  }),
  "type": Schema.Literal("thinking_mismatch_allowed").annotate({
    "title": "Type",
    "description": "Always `thinking_mismatch_allowed` for this entry type.",
    "default": "thinking_mismatch_allowed"
  })
}).annotate({
  "title": "ThinkingMismatchAllowedInputTransformation",
  "identifier": "BetaThinkingMismatchAllowedInputTransformation"
})
