export type BetaMessageDeltaEvent = {
  readonly "context_management"?: BetaResponseContextManagement | null
  readonly "delta": BetaMessageDelta
  readonly "input_transformations"?: ReadonlyArray<BetaInputTransformation> | null
  readonly "type": "message_delta"
  readonly "usage": BetaMessageDeltaUsage
}
export const BetaMessageDeltaEvent = Schema.Struct({
  "context_management": Schema.optionalKey(
    Schema.Union([BetaResponseContextManagement, Schema.Null]).annotate({
      "description": "Information about context management strategies applied during the request",
      "default": null
    })
  ),
  "delta": BetaMessageDelta,
  "input_transformations": Schema.optionalKey(
    Schema.Union([Schema.Array(BetaInputTransformation), Schema.Null]).annotate({
      "title": "Input Transformations",
      "description":
        "Changes the API made to the request's input before showing it to the model,\nand blocks that failed a binding check but were left unchanged: one entry per\nblock, in request order. Two entry types today. `thinking_dropped` — a\n`thinking`, `redacted_thinking` or `connector_text` block from the request's\n`messages` that was removed from the prompt instead of being shown to the\nmodel because it failed a binding check. `thinking_mismatch_allowed` — a\n`thinking` or `redacted_thinking` block that failed the conversation check\n(the conversation before it differs from the one it was created in, or it\ncarries no record of one on a model that requires it) and was shown to the\nmodel all the same, because that check is not enforced for this request.\nMore entry types may be added over time; ignore types you do not recognize.\n\nRequires `anthropic-beta: thinking-binding-controls-2026-08-01`. Present on\nevery such response from a model that supports extended thinking, as `[]`\nwhen there is no entry to report; without the beta, blocks are removed or\nleft in place all the same but nothing is reported. Removed blocks contribute\nnothing to `usage.input_tokens`; blocks left in place count as sent. When\nstreaming, the array is final in `message_start`; the final `message_delta`\nevent carries it only when a server-side model fallback happened mid-stream,\nin which case it holds the serving model's entries and replaces the one in\n`message_start`."
    })
  ),
  "type": Schema.Literal("message_delta").annotate({ "title": "Type", "default": "message_delta" }),
  "usage": Schema.suspend((): Schema.Codec<BetaMessageDeltaUsage> => BetaMessageDeltaUsage).annotate({
    "description":
      "Billing and rate-limit usage.\n\nAnthropic's API bills and rate-limits by token counts, as tokens represent the underlying cost to our systems.\n\nUnder the hood, the API transforms requests into a format suitable for the model. The model's output then goes through a parsing stage before becoming an API response. As a result, the token counts in `usage` will not match one-to-one with the exact visible content of an API request or response.\n\nFor example, `output_tokens` will be non-zero, even for an empty string response from Claude.\n\nTotal input tokens in a request is the summation of `input_tokens`, `cache_creation_input_tokens`, and `cache_read_input_tokens`."
  })
}).annotate({ "title": "MessageDeltaEvent", "identifier": "BetaMessageDeltaEvent" })
